CREATE TABLE branches (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, address VARCHAR(255) NOT NULL, phone VARCHAR(20) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE app_users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, full_name VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('ADMIN','MANAGER','WAITER','CHEF')), branch_id BIGINT REFERENCES branches(id), active BOOLEAN NOT NULL DEFAULT TRUE, token_version INTEGER NOT NULL DEFAULT 0, CHECK(role='ADMIN' OR branch_id IS NOT NULL));
CREATE TABLE categories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE dishes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, description VARCHAR(1000) NOT NULL, price NUMERIC(14,0) NOT NULL CHECK(price>0), category_id BIGINT NOT NULL REFERENCES categories(id), image_url VARCHAR(500) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE branch_dishes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, branch_id BIGINT NOT NULL REFERENCES branches(id), dish_id BIGINT NOT NULL REFERENCES dishes(id), available BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(branch_id,dish_id));
CREATE TABLE restaurant_tables (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, branch_id BIGINT NOT NULL REFERENCES branches(id), label VARCHAR(30) NOT NULL, capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 30), qr_key VARCHAR(36) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(branch_id,label));
CREATE TABLE dining_sessions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, table_id BIGINT NOT NULL REFERENCES restaurant_tables(id), opened_at TIMESTAMP WITH TIME ZONE NOT NULL, closed_at TIMESTAMP WITH TIME ZONE, CHECK(closed_at IS NULL OR closed_at>=opened_at));
CREATE UNIQUE INDEX uq_one_open_session_per_table ON dining_sessions(table_id) WHERE closed_at IS NULL;
CREATE TABLE food_orders (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, session_id BIGINT NOT NULL REFERENCES dining_sessions(id), status VARCHAR(20) NOT NULL CHECK(status IN ('NEW','CONFIRMED','COOKING','READY','SERVED','CANCELLED')), note VARCHAR(500) NOT NULL, request_key VARCHAR(36) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, version BIGINT, UNIQUE(session_id,request_key));
CREATE TABLE order_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES food_orders(id), dish_id BIGINT NOT NULL REFERENCES dishes(id), dish_name VARCHAR(120) NOT NULL, unit_price NUMERIC(14,0) NOT NULL CHECK(unit_price>0), quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 20));
CREATE TABLE invoices (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, session_id BIGINT NOT NULL UNIQUE REFERENCES dining_sessions(id), subtotal NUMERIC(14,0) NOT NULL CHECK(subtotal>0), discount_amount NUMERIC(14,0) NOT NULL CHECK(discount_amount>=0), total NUMERIC(14,0) NOT NULL CHECK(total=subtotal-discount_amount AND total>0), method VARCHAR(20) NOT NULL CHECK(method IN ('CASH','BANK_TRANSFER')), paid_at TIMESTAMP WITH TIME ZONE NOT NULL, cashier VARCHAR(100) NOT NULL);
CREATE TABLE service_calls (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, session_id BIGINT NOT NULL REFERENCES dining_sessions(id), message VARCHAR(120) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, resolved_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE audit_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor VARCHAR(100) NOT NULL, action VARCHAR(80) NOT NULL, detail VARCHAR(500) NOT NULL, branch_id BIGINT, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_orders_session_status ON food_orders(session_id,status);
CREATE INDEX idx_invoice_paid ON invoices(paid_at);
CREATE INDEX idx_tables_branch ON restaurant_tables(branch_id);
CREATE INDEX idx_service_calls_open ON service_calls(session_id,resolved_at);
